<script setup lang="ts">
import Icon from './Icon.vue'
import type {AppState,Page} from '../../shared/contracts.ts'
import type {PlaybackLibrary,PlayerCommand,PlayerState} from '../../shared/playback.ts'
import type {TrackReference} from '../../shared/music.ts'
import {bindingText,phaseText,playTime,qualityText} from '../playback-ui.ts'
const props=defineProps<{page:Page;player:PlayerState|null;library:PlaybackLibrary|null;app:AppState|null}>()
const emit=defineEmits<{command:[command:PlayerCommand];inspect:[reference:TrackReference];collection:[id:string];importLocal:[];removeLocal:[id:string];playHistory:[id:string];clearHistory:[];back:[]}>()
const headings={now:['NOW PLAYING','正在播放'],history:['LISTENING HISTORY','播放历史'],review:['VERSION REVIEW','待处理歌曲'],local:['LOCAL MUSIC','本地音乐']} as const
function date(at:string):string{return new Date(at).toLocaleString('zh-CN',{hour12:false})}
</script>
<template>
  <section class="page playback-page">
    <div class="page-heading"><div><p class="eyebrow">{{ headings[page as keyof typeof headings]?.[0] }}</p><h1>{{ headings[page as keyof typeof headings]?.[1] }}</h1><p v-if="page==='history'" class="page-description">保留真正播放过的版本和来源。</p><p v-if="page==='review'" class="page-description">对照疑问版本，重试资源或关联本地文件。</p><p v-if="page==='local'" class="page-description">添加 MP3、FLAC、WAV 文件，在本机播放。</p></div><button v-if="page==='local'" class="button primary" data-local-import @click="emit('importLocal')">添加本地音乐<Icon name="folder" /></button><button v-if="page==='history'&&library?.history.length" class="button" data-history-clear @click="emit('clearHistory')">清空播放历史</button></div>
    <template v-if="page==='now'"><button class="button back-button" @click="emit('back')"><Icon name="back" />返回浏览</button><div v-if="player?.now" class="now-card" data-now-playing><div class="now-art" aria-hidden="true"><Icon name="disc" /><span>NOW / {{ player.now.fromCache?'CACHE':'PLAY' }}</span></div><div class="now-details"><p class="eyebrow">{{ phaseText(player.phase) }}</p><h2>{{ player.now.title }}</h2><p class="now-artist">{{ player.now.artist??'歌手资料待补充' }}</p><p>{{ player.now.album??'专辑资料待补充' }}<span v-if="player.now.version"> · {{ player.now.version }}</span></p><p class="now-quality">{{ qualityText(player.now) }} · {{ playTime(player.durationMs??player.now.expectedDurationMs) }}<span v-if="player.now.fromCache"> · 歌曲缓存</span></p><p class="source-note">{{ player.now.source }}<span v-if="player.now.verifiedBitrateKbps"> · 音质来自音频头部</span></p><p v-if="['alternative','local'].includes(player.now.binding)" class="inline-warning">{{ bindingText(player.now) }}<span v-if="player.now.original"> · 收藏记录：{{ player.now.original.title??player.now.original.filename }}（{{ playTime(player.now.original.durationMs) }}）</span></p><div class="playback-actions"><button class="button primary" @click="emit('command',{type:'control',action:player.desiredPlaying?'pause':'resume'})"><Icon :name="player.desiredPlaying?'pause':'play'" />{{ player.desiredPlaying?'暂停':'继续播放' }}</button><button v-if="player.now.reference" class="button" @click="emit('inspect',player.now.reference)">对照收藏版本</button><button v-if="player.now.reference&&app?.library.collections.some(item=>item.id===player!.now!.reference!.collectionId)" class="button" @click="emit('collection',player.now.reference.collectionId)">回到来源歌单</button></div><p v-if="player.reason" class="inline-warning">{{ player.reason }}</p></div></div><div v-else class="empty-stage"><div class="empty-art"><Icon name="disc" /></div><h2>还没有正在播放的音乐</h2><p>在歌单中双击曲目，或添加本地音乐开始播放。</p></div></template>
    <template v-else-if="page==='history'"><div v-if="library?.history.length" class="playback-items"><article v-for="entry in library.history" :key="entry.id" class="playback-item" data-history-item><div><h3>{{ entry.now.title }}<span v-if="entry.now.binding==='alternative'||entry.now.binding==='local'" class="version-label">{{ bindingText(entry.now) }}</span></h3><p>{{ entry.now.artist??'本地音乐' }} · {{ playTime(entry.now.observedDurationMs ?? entry.now.expectedDurationMs) }}</p><p class="source-note">{{ date(entry.at) }} · {{ entry.now.source }}<span v-if="entry.now.collectionName"> · {{ entry.now.collectionName }}</span> · 已播放 {{ playTime(entry.playedMs) }}<span v-if="entry.completed"> · 播放至结束</span></p></div><div class="playback-actions"><button class="button" @click="emit('playHistory',entry.id)"><Icon name="play" />再播放</button><button v-if="entry.now.reference&&app?.library.collections.some(item=>item.id===entry.now.reference!.collectionId)" class="button" @click="emit('collection',entry.now.reference.collectionId)">来源歌单</button></div></article></div><div v-else class="empty-stage"><div class="empty-art"><Icon name="history" /></div><h2>还没有播放记录</h2><p>真正播放过的音乐，会留在这里。</p></div><p v-if="library?.history.length===200" class="source-note">显示最近 200 条播放记录。</p></template>
    <template v-else-if="page==='local'"><div v-if="library?.local.length" class="playback-items"><article v-for="item in library.local" :key="item.id" class="playback-item" data-local-item><div><h3>{{ item.name }}</h3><p>{{ item.format }} · {{ playTime(item.durationMs) }}<span v-if="item.bitrateKbps"> · {{ item.bitrateKbps }} kbps</span></p><p v-if="item.missing" class="comparison-reason">文件缺失或已改变，请重新添加或关联。</p><p v-else class="source-note">添加于 {{ date(item.addedAt) }}</p></div><div class="playback-actions"><button class="button" :disabled="item.missing" @click="emit('command',{type:'play',target:{kind:'local',localId:item.id}})"><Icon name="play" />播放</button><button class="button" :disabled="item.missing" @click="emit('command',{type:'enqueue',target:{kind:'local',localId:item.id},placement:'end'})">加入队列</button><button class="button" @click="emit('removeLocal',item.id)">移出列表</button></div></article><p class="source-note">移出列表会保留原音频文件。可在歌单的版本对照中关联本地文件。</p></div><div v-else class="empty-stage"><div class="empty-art"><Icon name="folder" /></div><h2>添加熟悉的本地音乐</h2><p>本地文件可单独播放，也可关联到收藏曲目。</p><button class="button primary" @click="emit('importLocal')">添加本地音乐<Icon name="folder" /></button></div></template>
    <template v-else-if="page==='review'"><div v-if="library?.issues.length" class="playback-items"><article v-for="(item,index) in library.issues" :key="item.reference.collectionId+':'+item.reference.position" class="playback-item" data-review-item><div><h3>{{ item.title }}</h3><p class="source-note">{{ item.collectionName }} · 第 {{ item.reference.position }} 首</p><p class="comparison-reason">{{ item.reason }}</p></div><div class="playback-actions"><button class="button" @click="emit('inspect',item.reference)">选择版本</button><button class="button" @click="emit('command',{type:'play',target:{kind:'original',reference:item.reference}})">重试播放</button></div></article></div><div v-else class="empty-stage"><div class="empty-art"><Icon name="review" /></div><h2>暂时没有待处理歌曲</h2><p>检查或播放中发现的版本疑问和资源问题，会显示在这里。</p></div><p v-if="library?.issues.length===300" class="source-note">显示前 300 个待处理位置。</p></template>
  </section>
</template>
